        placeholder: "(555) 123-4567",
        required: false,
        helperText: "Optional. Use digits with an area code, such as (555) 123-4567 or +1 555 123 4567."
      }
    ];

    function escapeHtml(value) {
      return value.replace(/[&<>"']/g, function(character) {
        const entities = {
          "&": "&amp;",
          "<": "&lt;",
          ">": "&gt;",
          '"': "&quot;",
          "'": "&#39;"
        };
        return entities[character];
      });
    }

    function TextField(field) {
      const helperId = field.helperText ? field.id + "-helper" : "";
      const errorId = field.id + "-error";
      const describedBy = [helperId, errorId].filter(Boolean).join(" ");

      return `
        <div class="form-field">
          <label for="${field.id}">${field.label}${field.required ? " *" : ""}</label>
          <input
            id="${field.id}"
            name="${field.id}"
            type="${field.type}"
            placeholder="${escapeHtml(field.placeholder)}"
            ${field.required ? "required" : ""}
            ${describedBy ? `aria-describedby="${describedBy}"` : ""}
          />
          ${field.helperText ? `<p class="helper-text" id="${helperId}">${field.helperText}</p>` : ""}
          <p class="field-error" id="${errorId}" aria-live="polite"></p>
