      return `
        <form id="support-form" novalidate>
          ${fields.map(TextField).join("")}
          <div class="submit-row">
            <button class="submit-button" type="submit">Submit request</button>
          </div>
          <p class="status-message" id="form-status" aria-live="polite"></p>
        </form>
      `;
    }

