     function SupportPage() {
       return `
         <main class="app-shell">
           <section class="support-card" aria-labelledby="support-heading">
             <div class="eyebrow">Support team</div>
             <h1 id="support-heading">Contact support</h1>
             <p class="lead">
               Tell us how we can help and a specialist will reach out with the next steps.
             </p>
             ${ContactForm()}
           </section>
         </main>
       `;
     }

     document.getElementById("app").innerHTML = SupportPage();

     const form = document.getElementById("support-form");
     const statusMessage = document.getElementById("form-status");

     function showError(input, message) {
       const errorElement = document.getElementById(input.id + "-error");
       errorElement.textContent = message;
       input.setAttribute("aria-invalid", "true");
     }

     function clearError(input) {
       const errorElement = document.getElementById(input.id + "-error");
       errorElement.textContent = "";
       input.removeAttribute("aria-invalid");
     }

     function validateField(input) {
       const value = input.value.trim();

       if (input.name === "fullName" && !value) {
         showError(input, "Please enter your full name.");
         return false;
       }

       if (input.name === "email") {
         if (!value) {
           showError(input, "Please enter your email address.");
           return false;
         }

         if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)) {
           showError(input, "Please enter a valid email address.");
           return false;
         }
       }

       if (input.name === "phone" && value && !/^[+\d\s().-]{7,}$/.test(value)) {
         showError(input, "Please use the phone format shown in the helper text.");
         return false;
       }

       clearError(input);
       return true;
     }

     fields.forEach(function(field) {
       const input = document.getElementById(field.id);
       input.addEventListener("blur", function() {
         validateField(input);
       });
       input.addEventListener("input", function() {
         if (document.getElementById(field.id + "-error").textContent) {
           validateField(input);
         }
       });
     });

     form.addEventListener("submit", function(event) {
       event.preventDefault();

       const inputs = fields.map(function(field) {
         return document.getElementById(field.id);
       });

       const allValid = inputs.map(validateField).every(Boolean);

       if (!allValid) {
         statusMessage.textContent = "Please review the highlighted fields and try again.";
         const firstInvalid = inputs.find(function(input) {
           return input.getAttribute("aria-invalid") === "true";
         });
         if (firstInvalid) {
           firstInvalid.focus();
         }
         return;
       }

       statusMessage.textContent = "Thanks. Your support request is ready to send.";
       form.reset();
       inputs.forEach(clearError);
     });
   </script>
 </body>
 </html>

